#define main historical_main
#include "../norm2-cuda/main.cu"
#undef main
#include <vector>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
#define BK(x) do{if((x)!=CUBLAS_STATUS_SUCCESS){fprintf(stderr,"CUBLAS failure\n");exit(3);}}while(0)
struct Case{float*a,gold;int n;};
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;if(repeat<1)return 2;cublasHandle_t h;BK(cublasCreate(&h));BK(cublasSetPointerMode(h,CUBLAS_POINTER_MODE_HOST));std::vector<Case>cases;for(int n:{524288,1048576}){std::vector<float>a(n);double sum=0;for(int i=0;i<n;i++){a[i]=(i+1)%7;sum+=double(a[i])*a[i];}Case c;c.n=n;c.gold=float(sqrt(sum));CK(cudaMalloc(&c.a,n*sizeof(float)));CK(cudaMemcpy(c.a,a.data(),n*sizeof(float),cudaMemcpyHostToDevice));float warm;BK(cublasSnrm2(h,n,c.a,1,&warm));cases.push_back(c);}CK(cudaDeviceSynchronize());bool allok=true;for(int trial=1;trial<=5;trial++){double seconds=0,ma=0,times[2];int ci=0;std::vector<float>out;bool ok=true;for(auto&c:cases){std::vector<float>got(repeat);CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++){BK(cublasSnrm2(h,c.n,c.a,1,&got[rep]));}CK(cudaDeviceSynchronize());times[ci++]=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;seconds+=times[ci-1];for(float x:got){ma=fmax(ma,fabs(x-c.gold));ok&=std::isfinite(x)&&fabs(x-c.gold)<=.1;}out.insert(out.end(),got.begin(),got.end());}allok&=ok;char file[80];sprintf(file,"norm2_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(out.data(),sizeof(float),out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"timing_region\":\"sum_two_sizes_full_norm_plus_host_scalar_result_every_call\",\"jit_excluded\":true,\"internal_repeats\":%d,\"size_times_seconds\":[%.12g,%.12g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",out.size(),ma,repeat,times[0],times[1],file,out.size());}for(auto&c:cases)CK(cudaFree(c.a));BK(cublasDestroy(h));puts(allok?"PASS":"FAIL");return allok?0:1;}
